// Header types (often <time.h>)
typedef long clock_t;
#define CLOCKS_PER_SEC 1000000L

clock_t start, end;
double duration_s;

start = clock();

// --- Code segment being benchmarked ---
// ... loop or complex calculation ...
// ------------------------------------

end = clock();

// Calculate CPU time elapsed in seconds
duration_s = ((double)(end - start)) / CLOCKS_PER_SEC;
